type Role = "viewer" | "editor" | "owner";
type Action = "read" | "edit" | "delete";

const REQUIRED: Record<Action, Role> = { read: "viewer", edit: "editor", delete: "owner" };
const RANK: Record<Role, number> = { viewer: 1, editor: 2, owner: 3 };

interface Resource {
  id: string;
  parentId: string | null;
}

export async function canAccess(
  userId: string,
  resource: Resource,
  action: Action,
  grants: GrantRepo,
  resources: ResourceRepo,
): Promise<boolean> {
  const needed = RANK[REQUIRED[action]];
  let current: Resource | null = resource;
  while (current) {
    const role = await grants.roleFor(userId, current.id);
    if (role && RANK[role] >= needed) return true;
    current = current.parentId ? await resources.get(current.parentId) : null;
  }
  return false;
}
